CREATE OR REPLACE FUNCTION public.allocate_order_invoice(p_order uuid) RETURNS text LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE o public.orders; cfg jsonb; num int; result text; BEGIN SELECT * INTO o FROM public.orders WHERE id=p_order FOR UPDATE; IF NOT FOUND OR o.status<>'paid' THEN RAISE EXCEPTION 'Bezahlte Bestellung erforderlich.'; END IF; IF o.invoice_number IS NOT NULL THEN RETURN o.invoice_number; END IF; SELECT value INTO cfg FROM public.settings WHERE key='invoice' FOR UPDATE; IF NOT FOUND THEN result:='RE-'||extract(year FROM now())::text||'-'||o.id::text; ELSE num:=GREATEST(1,COALESCE((cfg->>'next_number')::int,1)); result:=COALESCE(cfg->>'prefix','RE')||'-'||extract(year FROM now())::text||'-'||lpad(num::text,4,'0'); UPDATE public.settings SET value=jsonb_set(cfg,'{next_number}',to_jsonb(num+1)),updated_at=now() WHERE key='invoice'; END IF; UPDATE public.orders SET invoice_number=result WHERE id=o.id; RETURN result; END; $$;
REVOKE ALL ON FUNCTION public.allocate_order_invoice(uuid) FROM PUBLIC,anon,authenticated; GRANT EXECUTE ON FUNCTION public.allocate_order_invoice(uuid) TO service_role;
DROP POLICY IF EXISTS "Visitors can update own session" ON public.page_visits;
DROP POLICY IF EXISTS "Anyone can read settings" ON public.settings;
DROP POLICY IF EXISTS "Anyone can view settings" ON public.settings;
CREATE POLICY "Only public presentation settings" ON public.settings AS RESTRICTIVE FOR SELECT TO anon,authenticated USING(key IN ('features','alfred_butler','support_online','wrapped_config','wrapped_fallback_song','instagram_posts','ticket_template') OR public.has_role((select auth.uid()),'admin'));
CREATE POLICY "Bounded U18 public submissions" ON public.u18_forms AS RESTRICTIVE FOR INSERT TO anon,authenticated WITH CHECK(length(trim(parent_name)) BETWEEN 1 AND 100 AND length(trim(minor_name)) BETWEEN 1 AND 100 AND length(parent_address) BETWEEN 1 AND 500 AND length(minor_address) BETWEEN 1 AND 500 AND length(parent_phone) BETWEEN 1 AND 100 AND length(minor_phone) BETWEEN 1 AND 100 AND length(email)<=255);
CREATE OR REPLACE FUNCTION public.get_order_confirmation(_order_id uuid) RETURNS jsonb LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT jsonb_build_object('order',jsonb_build_object('id',o.id,'status',o.status,'email',o.email,'name',o.name,'event_id',o.event_id,'items',o.items,'total_amount',o.total_amount,'currency',o.currency,'service_fee',o.service_fee,'insurance_fee',o.insurance_fee,'created_at',o.created_at,'paid_at',o.paid_at),'tickets',CASE WHEN o.status='paid' THEN COALESCE((SELECT jsonb_agg(jsonb_build_object('id',t.id,'qr_code',t.qr_code,'status',t.status,'holder_name',t.holder_name,'ticket_category_id',t.ticket_category_id,'event_id',t.event_id)) FROM public.tickets t WHERE t.order_id=o.id AND lower(COALESCE(t.holder_email,''))=lower(o.email)),'[]'::jsonb) ELSE '[]'::jsonb END) FROM public.orders o WHERE o.id=_order_id $$;